fn all_prefixes(s: Vec<char>) -> Vec<Vec<char>> {
    // Prepare a result vector with the same capacity as the input length.
    let mut result: Vec<Vec<char>> = Vec::with_capacity(s.len());
    // This will hold the current growing prefix.
    let mut prefix: Vec<char> = Vec::new();

    // Iterate through each character in the input.
    for c in s {
        // Extend the current prefix by the new character.
        prefix.push(c);
        // Clone the prefix and add it to the result list.
        result.push(prefix.clone());
    }

    result
}

fn main() {
    // Example usages:
    let v1: Vec<char> = vec!['a', 'b', 'c', 'd'];
    let p1 = all_prefixes(v1);
    // p1 == [["a"], ["a","b"], ["a","b","c"], ["a","b","c","d"]]

    let v2: Vec<char> = vec![];
    let p2 = all_prefixes(v2);
    // p2 == []
    
    println!("{:?}", p1);
    println!("{:?}", p2);
}